<script setup>
import Icon from './Icon.vue';import StatusBadge from './StatusBadge.vue';import {dateLabel} from '../utils/shipments.js';
defineProps({items:Array,sort:String,direction:String,compact:Boolean});const emit=defineEmits(['open','sort']);
</script>
<template><div class="table-scroll"><table class="shipment-table" :class="{compact}"><thead><tr><th v-for="c in [{key:'id',label:'Shipment'},{key:'customer',label:'Customer'},{key:'origin',label:'Route'},{key:'status',label:'Status'},{key:'eta',label:'Arrival'}]" :aria-sort="sort===c.key?(direction==='asc'?'ascending':'descending'):'none'"><button @click="emit('sort',c.key)">{{c.label}}<Icon v-if="sort===c.key" :name="direction==='asc'?'ArrowUp':'ArrowDown'" :size="12"/><Icon v-else name="ChevronDown" :size="12"/></button></th><th><span class="sr-only">Details</span></th></tr></thead><tbody><tr v-for="s in items" :key="s.id"><td><button class="shipment-id" @click="emit('open',s)"><span class="mode-icon"><Icon :name="s.mode==='Ocean'?'Ship':s.mode==='Road'?'Truck':'Plane'" :size="18"/></span><span>{{s.id}}<small>{{s.mode}} freight</small></span></button></td><td>{{s.customer}}<small>{{s.reference||'No reference'}}</small></td><td><span class="route-cell">{{s.origin}}<Icon name="ArrowRight" :size="12"/>{{s.destination}}</span><small>{{s.originCountry||'International'}} → {{s.destinationCountry||'International'}}</small></td><td><StatusBadge :status="s.status"/></td><td>{{dateLabel(s.eta)}}<small>{{s.status==='Delivered'?'Delivery complete':'Estimated arrival'}}</small></td><td><button class="icon-button" @click="emit('open',s)" :aria-label="`View ${s.id}`"><Icon name="ArrowUpRight" :size="17"/></button></td></tr></tbody></table></div></template>
